#!/usr/bin/env dotnet
#:property AllowUnsafeBlocks=true

Console.WriteLine($"IntPtr.Size = {IntPtr.Size} bytes ({"64-bit" if IntPtr.Size == 8 else "32-bit"} platform)");
Console.WriteLine();

// stackalloc nint (signed native-sized integer)
Span<nint> signed = stackalloc nint[4];
for (int i = 0; i < signed.Length; i++)
    signed[i] = (nint)(i * 100);

Console.WriteLine("Span<nint> via stackalloc:");
for (int i = 0; i < signed.Length; i++)
    Console.WriteLine($"  [{i}] = {signed[i]}");

Console.WriteLine();

// stackalloc nuint (unsigned native-sized integer)
Span<nuint> unsigned = stackalloc nuint[4];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i * 200);

Console.WriteLine("Span<nuint> via stackalloc:");
for (int i = 0; i < unsigned.Length; i++)
    Console.WriteLine($"  [{i}] = {unsigned[i]}");

Console.WriteLine();
Console.WriteLine($"sizeof(nint)  = {sizeof(nint)} bytes");
Console.WriteLine($"sizeof(nuint) = {sizeof(nuint)} bytes");

